"""Работа юнита и рост города — факты из ветки `v2` (§10.116, §10.117 её журнала).

Переносятся ФАКТЫ О МИРЕ, а не выводы прежнего измерителя.

1. **«Действия нет в меню» ≠ «работа отпала».** Живой замер v2 (§10.117): мир ВЕДЁТ
   работу сам (extras 1 → 2), но перестаёт предлагать действие в меню, пока работа
   идёт, и повторная выдача отвергается («not valid»). Значит опыт нельзя гасить по
   пропаже действия из меню.
2. **Прерывание опыта — только реальный уход** (юнит погиб или сдвинулся, город
   потерян). Прежний счёт «действие исчезло из меню» гасил опыт на первом же ходу
   работы и навсегда блокировал повтор (четыре дефекта v2 перечислены в §10.117).
3. **Ценность типа, создающего город: `ln(DoF СОЗДАВАЕМОГО города) × frac`** (§10.116).
   Множитель — DoF города (аксиома 6: плод, а не собственный набор возможностей юнита),
   но горизонтный дисконт `frac` ПРИМЕНЯЕТСЯ, как у прочих построек. **Вариант «без frac»
   был ИСПЫТАН И ОТВЕРГНУТ**: без дисконта цена поселенца 3.091 поднимается над воином
   (2.197) и вытесняет военную постройку целиком (A — 0 военных, выжил 5/10; B — 8/10;
   медиана −8, эффект не установлен). До правки было наоборот: поселенец считался по
   СВОЕМУ DoF 13 при сроке 38 → дисконт 0.14 → цена 0.352, ниже воина 2.197, и
   `produce_Settlers` за серию выбирался **0 раз**. Соразмерная форма армию не вытесняет:
   поселенец обгоняет воина только когда город строит его за eta ≤ 7 ходов.
4. **Ценность поселенца — не только производство.** В v2 к ней ещё входят: `cover` —
   доля выживания под ударом (своя армия рядом риск снимает), `C_pop` — цена жителя
   (поселенец стоит 2 населения: `ln(DoF(s)) − ln(DoF(s−2))`), `settler_spacing_factor`
   (§10.108 — под своим городом поселенец дешевеет) и `settler_uncrowding_gain` (уход
   прочь от города даёт выигрыш). Это механизмы, а не выводы: при переносе они едут
   вместе с ценностью.
5. **Тип определяется СПОСОБНОСТЬЮ, а не именем.** Если паспорт отдаёт способности
   позиционным массивом без имён (на нашей съёмке `flags` — числа), способность **не
   читается**: возвращается `None` **с причиной**, а не «способности нет» — незнание не
   превращается в отсутствие.
6. **Рост города** (замер v2): излишек еды медиана **+0** при размере 1 и **+1** при 2–4;
   **42 %** записей — прирост 0.
"""
from __future__ import annotations

import math

from typing import Any, Mapping, Optional

#: Излишек еды по размеру города — измеренные медианы (`v2`, §10.117).
GROWTH_SURPLUS_MEDIAN_BY_SIZE: dict[int, float] = {1: 0.0, 2: 1.0, 3: 1.0, 4: 1.0}
#: Доля записей с нулевым приростом (`v2`, §10.117) — город «стоит».
GROWTH_ZERO_SHARE: float = 0.42

#: Имена способностей, которыми паспорт типа может объявить «этот тип создаёт город».
CITY_MAKING_ABILITY_KEYS: tuple[str, ...] = (
    "build_city", "can_found_city", "found_city", "city_founder",
)


def work_continues_without_menu(menu_has_action: bool,
                                extras_changed: bool) -> tuple[bool, str]:
    """Работа идёт, хотя действия нет в меню: `(идёт, причина)`.

    Замер v2 (§10.117): мир ведёт работу сам, а действие прячет из меню. Поэтому
    отсутствие действия **не** означает, что работа отпала; судить по одному меню —
    значит погасить опыт на первом же ходу работы.
    """
    if menu_has_action:
        return False, "действие в меню — работа ведётся явно"
    if extras_changed:
        return True, ("действия нет в меню, но extras изменились: мир ведёт работу сам "
                      "(замер v2: extras 1 → 2)")
    return False, "действия нет и extras не менялись — работа не наблюдена"


def interrupted_by_real_departure(actor_alive: bool, actor_moved: bool,
                                  city_lost: bool) -> tuple[bool, str]:
    """Прерывание опыта — только реальный уход актора: `(прервано, причина)`.

    Прежний счёт («действие исчезло из меню») гасил опыт на первом ходу работы;
    настоящий уход — это гибель юнита, его перемещение или потеря города.
    """
    if not actor_alive:
        return True, "актор погиб/исчез — прерывание по делу"
    if actor_moved:
        return True, "актор сдвинулся (`goto`) — прерывание по делу"
    if city_lost:
        return True, "город потерян — прерывание по делу"
    return False, "актор на месте и жив — опыт продолжается, прерывания нет"


def creates_city(spec: Mapping[str, Any]) -> tuple[Optional[bool], str]:
    """Создаёт ли тип город — по СПОСОБНОСТИ паспорта, а не по имени: `(да/нет/None, причина)`.

    Имя типа доказательством не является («Settlers» может не создавать город, а
    другой тип — создавать). Если паспорт объявляет способности позиционным массивом
    без имён (на съёмке `flags` = числа), способность НЕ читается — `None` с причиной.
    """
    if not isinstance(spec, Mapping):
        return None, "паспорт типа не отдан наблюдением — способность не читается"
    for key in CITY_MAKING_ABILITY_KEYS:
        if spec.get(key) is True:
            return True, f"паспорт объявляет способность `{key}`"
    flags = spec.get("flags")
    if isinstance(flags, str) and "city" in flags.lower():
        return True, f"в строковых flags есть признак города: {flags}"
    if flags is not None:
        return None, ("flags — позиционный массив без имён (на съёмке: числа), "
                      "способность по нему не читается")
    return None, "способность в паспорте не названа — незнание, а не отсутствие"


#: ФОРМА ЦЕННОСТИ ГОРОДА-ТВОРЦА, принятая в v2 (§10.116), и форма, которую абляция
#: ОТВЕРГЛА. Множитель — DoF СОЗДАВАЕМОГО города (аксиома 6), но горизонтный
#: дисконт `frac` ПРИМЕНЯЕТСЯ, как у прочих построек. Вариант «без frac» был
#: ИСПЫТАН И ОТВЕРГНУТ: он поднял поселенца над воином и вытеснил всю военную
#: постройку (A — 0 военных, выжил 5/10; B — 8/10; медиана −8, эффект не
#: установлен). Соразмерная форма армию не вытесняет: поселенец обгоняет воина
#: (2.20) только когда город строит его за eta ≤ 7 ходов (крупный город).
CITY_MAKER_FORM = "ln(DoF создаваемого города) × frac"
CITY_MAKER_REJECTED_FORM = "ln(DoF создаваемого города) без frac (абляция §10.116 — отвергнута)"


def horizon_discount(eta: Optional[float],
                     horizon: float) -> tuple[Optional[float], str]:
    """Дисконт за горизонт: `min(1, H/eta)`. Считается для ВСЕХ построек.

    Флага «постоянного актива» здесь нет намеренно: отвергнутая абляция (§10.116)
    возвращается не настройкой, а правкой кода — так её нельзя включить случайно.
    Срок неизвестен — дисконт не считается (`None`), а не берётся «по памяти».
    """
    if eta is None or float(eta) <= 0.0:
        return None, "срок постройки неизвестен — дисконт не считается"
    return min(1.0, float(horizon) / float(eta)), (f"дисконт min(1, H/eta) = "
                                                   f"min(1, {float(horizon):g}/{float(eta):g})")


def city_maker_value(city_dof: Optional[float], eta: Optional[float], horizon: float
                     ) -> tuple[Optional[float], str]:
    """Ценность типа, создающего город: `ln(DoF города) × frac` — форма v2 (§10.116).

    `DoF города` — измеренный по городам (аксиома 6: множитель, а не собственный
    набор возможностей юнита). Не измерен — `None` с причиной: ценность не
    выдумывается. Перевод в `ln` здесь — пересказ формы v2 для сверки; в v0.11
    валюта своя (`DoF ∈ [0,1]`), поэтому числа этой функции НЕ являются счётом
    v0.11 и служат только проверкой переноса.
    """
    if city_dof is None or float(city_dof) <= 0.0:
        return None, "DoF города не измерен — ценность города-творца не считается"
    frac, why = horizon_discount(eta, horizon)
    if frac is None:
        return None, why
    return math.log(float(city_dof)) * frac, (f"ln({float(city_dof):g}) × {frac:.4f} = "
                                              f"{math.log(float(city_dof)) * frac:.3f} — {CITY_MAKER_FORM}")


def city_maker_value_without_discount(city_dof: Optional[float]) -> tuple[Optional[float], str]:
    """ОТВЕРГНУТАЯ абляцией форма — оставлена явно, чтобы её нельзя было вернуть случайно.

    Замер v2 (§10.116): без дисконта поселенец поднимается над воином и вытесняет
    военную постройку целиком. Функция существует как предупреждение и как число
    для сверки с записями v2, а не как вариант выбора.
    """
    if city_dof is None or float(city_dof) <= 0.0:
        return None, "DoF города не измерен"
    return math.log(float(city_dof)), (f"ln({float(city_dof):g}) = "
                                       f"{math.log(float(city_dof)):.3f} — {CITY_MAKER_REJECTED_FORM}")


#: Переходов предложено городу по его размеру — измеренные медианы (`v2`, §10.67:
#: 3 партии × 70 ходов, 70 наблюдений города). Рост 4 → 5 → 9 и есть «набор
#: возможностей города растёт вместе с городом».
#: ОГОВОРКИ БЕЗ СМЯГЧЕНИЯ (записаны v2 и повторены здесь): наблюдений мало (70),
#: размеры только 1–3, город один на партию — это НЕ статистический вывод, а первый
#: замер направления; рост числа переходов может идти не от размера, а от открытых
#: технологий — в тех данных два механизма не разделены.
CITY_TRANSITIONS_BY_SIZE: dict[int, float] = {1: 4.0, 2: 5.0, 3: 9.0}


def growth_raises_capability(size: Optional[int]) -> tuple[Optional[float], str]:
    """Растёт ли набор возможностей города с размером: `(переходов, причина)`.

    Ноль переходов — не рост: это закрытое окно съёмки (пустая секция города), и
    такие записи отсекаются тем же правилом, что и в `env.spec_eta.menu_is_measured`
    («пустое окно — не измерение»). Здесь правило не дублируется, а названо.
    Размер вне измеренного диапазона — `None` с причиной: средним по известным его
    заменять нечем, а нулём — запрещено.
    """
    if size is None:
        return None, "размер города не назван — сравнивать не с чем"
    measured = CITY_TRANSITIONS_BY_SIZE.get(int(size))
    if measured is None:
        return None, (f"размер {int(size)} не измерен (в замере были 1–3) — "
                      f"экстраполировать нечем")
    return measured, (f"измерено на живых партиях v2: размер {int(size)} → "
                      f"{measured:g} переходов (3 × 70 ходов, 70 наблюдений)")


def paths_limited_by_corridor(goals: int, paths_built: int,
                              cap: Optional[int]) -> tuple[bool, str]:
    """Ограничивал ли ход коридор путей: `(ограничивал, причина)`.

    Замер v2 (§10.105): у 10 юнитов были цели `explore` и законные направления, а
    путей построено **2** — потому что предел «не более двух путей одного вида цели»
    остался от эпохи «одно действие за ход». Предел — предохранитель, а не политика:
    дубли отсекаются «генуинно различными путями» по эффекту, а повтор — правилом
    «одна настройка на актора за ход».
    """
    if cap is None:
        return False, "предела нет — коридор не ограничивает"
    if goals > int(cap) and paths_built <= int(cap):
        return True, (f"целей {goals}, путей построено {paths_built} при пределе {int(cap)}: "
                      f"ходят не все, у кого есть цель (замер v2: 10 целей, 2 пути)")
    return False, f"предел {int(cap)} не связывает: целей {goals}, путей {paths_built}"


def frontier_cutoff_denies_goal(nearest_unrevealed: Optional[float],
                                threshold: Optional[float]) -> tuple[bool, str]:
    """Отсекает ли порог фронтира законную цель движения: `(отсекает, причина)`.

    Замер v2 (§10.105): порог `FRONTIER_REACH` (12, затем 30) лишал юнита цели, если
    ближайшая нераскрытая клетка дальше порога, — а движение к ней есть единственный
    источник нового DoF. Отсечка снята: цель даётся на любой дистанции; порог остаётся
    предохранителем, а не политикой.
    """
    if nearest_unrevealed is None:
        return False, "нераскрытых клеток рядом не наблюдено — цели нет по существу"
    if threshold is not None and float(nearest_unrevealed) > float(threshold):
        return True, (f"ближайшая нераскрытая клетка в {float(nearest_unrevealed):g} при пороге "
                      f"{float(threshold):g}: порог лишает цели (замер v2 — вреден)")
    return False, (f"ближайшая нераскрытая в {float(nearest_unrevealed):g} — "
                   f"цель даётся на любой дистанции")
